:root {
  --ink: #1f2328;
  --muted: #6e7781;
  --line: #d0d7de;
  --accent: #1f6feb;
  --bg: #f6f8fa;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
}
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background: #fff;
  border-bottom: 1px solid var(--line);
}
.app-header h1 { font-size: 15px; margin: 0; }
.app-header .ws-name { font-size: 13px; color: var(--muted); }
.toolbox {
  display: flex;
  gap: 8px;
  padding: 8px 18px;
  background: #fff;
  border-bottom: 1px solid var(--line);
}
.toolbox button {
  font-size: 12px;
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
}
.toolbox button.armed { border-color: var(--accent); color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.console-body { padding: 16px 18px; }
#master-host { margin-bottom: 14px; }
#linked-host {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
}
.panel-master { border-color: var(--accent); }
.panel-master.selecting { cursor: crosshair; }
.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 4px;
}
.panel-label { font-size: 12px; font-weight: 600; }
.panel-window {
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.panel-canvas { width: 100%; height: auto; display: block; }
.load-error { color: #cf222e; padding: 20px; }
.hint { font-size: 11px; color: var(--muted); padding: 0 18px 12px; }

